using Astrea.BattleActions;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "ChainedChantingCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/ChainedChantingCustomDescription", order = 0)]
public class ChainedChantingCustomDescription : CustomBattleActionDescription
{
	[SerializeField]
	private NonNormalChantingCustomDescription nonNormalChantingCustomDescription;

	[SerializeField]
	private MinimumSoulHeatBasedAction minimumSoulHeatBasedAction;

	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		ChainedChantingAction obj = battleAction as ChainedChantingAction;
		string firstArgument = nonNormalChantingCustomDescription.GetChantingDescriptionLocalized(battleAction).RemoveLast();
		firstArgument = base.localizationManager.GetLocalizedWhereXTimes(firstArgument, y: false, base.localizationManager.GetLocalizedHalfOfYourSoulHeat());
		string text = (obj.ResetSoulHeat ? ("\n" + base.localizationManager.GetLocalizedResetSoulHeat()) : "");
		return firstArgument + text;
	}
}
